CREATE TYPE "WorkEntryStatus" AS ENUM ('DRAFT','SUBMITTED','APPROVED','REJECTED','LOCKED'); CREATE TYPE "WorkEntrySource" AS ENUM ('MANUAL','CLOCK','OFFLINE_SYNC','MANAGER','IMPORT');
CREATE TABLE "WorkEntry" ("id" UUID NOT NULL,"companyId" UUID NOT NULL,"userId" UUID NOT NULL,"worksiteId" UUID,"date" DATE NOT NULL,"startTime" TIMESTAMPTZ(6),"endTime" TIMESTAMPTZ(6),"breakMinutes" INTEGER NOT NULL DEFAULT 0,"workedMinutes" INTEGER NOT NULL,"expectedMinutes" INTEGER NOT NULL,"differenceMinutes" INTEGER NOT NULL,"status" "WorkEntryStatus" NOT NULL DEFAULT 'DRAFT',"note" TEXT,"source" "WorkEntrySource" NOT NULL DEFAULT 'MANUAL',"createdByUserId" UUID,"updatedByUserId" UUID,"submittedAt" TIMESTAMPTZ(6),"approvedAt" TIMESTAMPTZ(6),"approvedByUserId" UUID,"rejectedAt" TIMESTAMPTZ(6),"rejectedByUserId" UUID,"rejectionReason" TEXT,"createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "WorkEntry_pkey" PRIMARY KEY("id"),CONSTRAINT "WorkEntry_times" CHECK ("endTime" IS NULL OR "startTime" IS NULL OR "endTime">"startTime"),CONSTRAINT "WorkEntry_minutes" CHECK ("breakMinutes">=0 AND "workedMinutes">=0));
CREATE INDEX "WorkEntry_companyId_userId_date_idx" ON "WorkEntry"("companyId","userId","date"); ALTER TABLE "WorkEntry" ADD CONSTRAINT "WorkEntry_companyId_fkey" FOREIGN KEY("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "WorkEntry" ADD CONSTRAINT "WorkEntry_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "WorkEntry" ADD CONSTRAINT "WorkEntry_worksiteId_fkey" FOREIGN KEY("worksiteId") REFERENCES "Worksite"("id") ON DELETE SET NULL; ALTER TABLE "WorkEntry" ENABLE ROW LEVEL SECURITY; ALTER TABLE "WorkEntry" FORCE ROW LEVEL SECURITY; CREATE POLICY "work_entry_tenant" ON "WorkEntry" FOR ALL USING("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK("companyId"=NULLIF(current_setting('app.company_id',true),'')::uuid);
CREATE FUNCTION "enforce_work_entry_tenant"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public."User" WHERE "id"=NEW."userId" AND "companyId"=NEW."companyId") OR (NEW."worksiteId" IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public."Worksite" WHERE "id"=NEW."worksiteId" AND "companyId"=NEW."companyId")) THEN RAISE EXCEPTION 'CROSS_TENANT_WORK_ENTRY'; END IF; RETURN NEW; END; $$; CREATE TRIGGER "WorkEntry_company_consistency" BEFORE INSERT OR UPDATE ON "WorkEntry" FOR EACH ROW EXECUTE FUNCTION "enforce_work_entry_tenant"();